 const meta=manifest.lessons.find(l=>l.id===id);const interview={id:meta.interviewId,lessonId:id,title:meta.title.replace(/^\[[A-D]\]\s*/,''),aliases:[`L${id}`,`lesson_${id}`],version:1,status:'drafted',modeType:meta.assessmentType,minutes:meta.minutes,brief,clarifications,hints,changes,rubric:manifest.rubric,referenceSolution,debrief,remediation};
